function Panel({title,subtitle,action,children,className=''}){return <section className={'panel '+className}><div className="panel-head"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>{children}</section>}
function StoreAvatar({store}){return <div className={'store-avatar avatar-'+(store.id%5)}><Store size={22}/></div>}
function SearchBox({value,onChange,placeholder='Buscar...'}){return <div className="searchbox"><Search size={17}/><input aria-label={placeholder} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/></div>}
function Modal({modal,close}){const ref=useRef();useEffect(()=>{if(!modal)return;const before=document.activeElement;document.body.style.overflow='hidden';ref.current?.focus();function key(e){if(e.key==='Escape')close();if(e.key==='Tab'){const list=[...ref.current.querySelectorAll('button,input,textarea,select,a[href],[tabindex="0"]')].filter(x=>!x.disabled&&!x.hidden);const a=list[0],b=list.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();b?.focus()}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a?.focus()}}}document.addEventListener('keydown',key);return()=>{document.body.style.overflow='';document.removeEventListener('keydown',key);before?.focus()}},[modal]);if(!modal)return null;return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&close()}><section className={'modal '+(modal.wide?'wide':'')} ref={ref} tabIndex={-1} role="dialog" aria-modal="true" aria-label={modal.title}><header><div><span className="eyebrow">NOWUP · ADM</span><h2>{modal.title}</h2></div><button className="icon-btn" aria-label="Fechar" onClick={close}><X/></button></header>{modal.body}</section></div>}
function FileField({label,name,initial='',onValue}){const [value,setValue]=useState(initial),[error,setError]=useState('');return <label className="field"><span>{label}</span><input type="hidden" name={name} value={value}/><input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>{const f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>650000){setError('Use PNG, JPG ou WebP de até 650 KB.');e.target.value='';return}setError('');const r=new FileReader();r.onload=()=>{setValue(String(r.result));onValue?.(String(r.result))};r.readAsDataURL(f)}}/>{value&&<img className="upload-preview" src={value} alt="Prévia da imagem"/>}{error&&<small className="text-red">{error}</small>}</label>}
