 function navigate(s){setModal(null);setSection(s);location.hash=s;setMobileMenu(false);window.scrollTo({top:0,behavior:'smooth'})}
 async function commit(mutator,reason){if(busy||mutationBusy())return;const next=structuredClone(data);try{mutator(next);const delta=changes(data,next);if(!delta.length){setToast('Nenhuma alteração disponível para salvar.');return}setBusy(true);const saved=await api('change',{revision:data._meta.revision,reason,changes:delta});setData(saved);setToast('Alteração confirmada pelo servidor.')}catch(e){setToast('Não salvo: '+e.message);try{setData(await api('state'))}catch{}}finally{setBusy(false)}}
 function form(title,fields,save,{submit='Salvar no servidor',wide=false}={}){setModal({title,wide,body:<form className="modal-content" onSubmit={e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));try{save(f);setModal(null)}catch(err){setToast(err.message)}}}>{fields}<footer><Button type="button" variant="secondary" onClick={()=>setModal(null)}>Cancelar</Button><Button type="submit" icon={Check}>{submit}</Button></footer></form>})}
 function confirm(title,text,action){setModal({title,body:<div className="modal-content"><p>{text}</p><footer><Button variant="secondary" onClick={()=>setModal(null)}>Voltar</Button><Button onClick={()=>{setModal(null);action()}}>Confirmar alteração</Button></footer></div>})}
 function logTable(logs=data.logs){return <div className="table-scroll"><table><thead><tr><th>Data e hora</th><th>Responsável</th><th>Ação</th></tr></thead><tbody>{logs.map(l=><tr key={l.id}><td>{new Date(l.date).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}</td><td>{l.actor}</td><td>{l.action}</td></tr>)}</tbody></table></div>}
 async function exportExcel(rows,name){try{const XLSX=await import('xlsx');const clean=rows.map(r=>Object.fromEntries(Object.entries(r).map(([k,v])=>[k,typeof v==='string'&&/^[=+@\-\t\r]/.test(v)?"'"+v:v])));const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(clean),'NowUp');XLSX.writeFile(wb,name+'.xlsx');setToast('Planilha exportada com os dados do filtro.')}catch{setToast('Não foi possível exportar. Tente novamente.')}}
 const report=useMemo(()=>sales(data.orders,data.stores,filter),[data.orders,data.stores,filter]);
